const configuredRepo = ($json.githubRepo || '').trim();
const [owner, repo] = configuredRepo.split('/');
if (!owner || !repo) {
  throw new Error('GITHUB_REPO must use owner/repo format, for example n8n-io/n8n');
}
const destinationEmail = ($json.destinationEmail || '').trim();
if (!destinationEmail) {
  throw new Error('DESTINATION_EMAIL is required for email delivery');
}
const language = (($json.language || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{
  json: {
    githubRepo: `${owner}/${repo}`,
    owner,
    repo,
    sinceIso: since.toISOString(),
    untilIso: until.toISOString(),
    sinceDate: since.toISOString().slice(0, 10),
    untilDate: until.toISOString().slice(0, 10),
    language,
    destinationEmail,
    emailFrom: $json.emailFrom || 'Weekly Dev Summary <onboarding@resend.dev>'
  }
}];

const config = $('Build Weekly Config').first().json;
const commitItems = $('Fetch Commits').all().map((item) => item.json).filter((commit) => commit.sha || commit.commit);
const issueSearch = $('Fetch Closed Issues').first().json;
const prSearch = $('Fetch Merged PRs').first().json;
const compactCommits = commitItems.slice(0, 50).map((commit) => ({
  sha: (commit.sha || '').slice(0, 7),
  message: (commit.commit?.message || '').split('\n')[0],
  author: commit.commit?.author?.name || commit.author?.login || 'unknown',
  date: commit.commit?.author?.date || null,
  url: commit.html_url
}));
const compactIssues = (issueSearch.items || []).slice(0, 50).map((issue) => ({
  number: issue.number,
  title: issue.title,
  closedAt: issue.closed_at,
  url: issue.html_url
}));
const compactPrs = (prSearch.items || []).slice(0, 50).map((pr) => ({
  number: pr.number,
  title: pr.title,
  mergedAt: pr.closed_at,
  author: pr.user?.login || 'unknown',
  url: pr.html_url
}));
const counts = {
  commits: commitItems.length,
  closedIssues: issueSearch.total_count || compactIssues.length,
  mergedPrs: prSearch.total_count || compactPrs.length
};
const languageInstruction = config.language === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';
const prompt = `${languageInstruction}\n\nCreate a concise weekly engineering narrative for ${config.githubRepo}. Use this structure: Overview, Highlights, Merged PRs, Closed Issues, and Follow-ups. Cite PR or issue numbers when available. Do not invent activity that is not present in the data. If there is little activity, say that plainly.\n\nWindow: ${config.sinceIso} to ${config.untilIso}\n\nCounts:\n${JSON.stringify(counts, null, 2)}\n\nCommits:\n${JSON.stringify(compactCommits, null, 2)}\n\nClosed issues:\n${JSON.stringify(compactIssues, null, 2)}\n\nMerged PRs:\n${JSON.stringify(compactPrs, null, 2)}`;
return [{
  json: {
    ...config,
    counts,
    commits: compactCommits,
    closedIssues: compactIssues,
    mergedPrs: compactPrs,
    prompt
  }
}];

const context = $('Build Claude Request').first().json;
const response = $json;
const summary = response.content?.map((part) => part.text || '').join('\n').trim() || 'Claude returned an empty summary.';
const subject = `Weekly dev summary: ${context.githubRepo} (${context.sinceDate} to ${context.untilDate})`;
const escapedSummary = summary.replace(/[&<>]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[char]));
return [{
  json: {
    emailFrom: context.emailFrom,
    emailTo: context.destinationEmail,
    subject,
    text: `Weekly dev summary for ${context.githubRepo}\n\n${summary}`,
    html: `<h1>Weekly dev summary for ${context.githubRepo}</h1><pre style="white-space: pre-wrap; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;">${escapedSummary}</pre>`
  }
}];
